CREATE TABLE IF NOT EXISTS "erp_product" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "name" varchar(128) DEFAULT NULL,
    "bar_code" varchar(64) DEFAULT NULL,
    "category_id" bigint DEFAULT NULL,
    "unit_id" bigint DEFAULT NULL,
    "status" int DEFAULT NULL,
    "standard" varchar(1024) DEFAULT NULL,
    "remark" varchar(512) DEFAULT NULL,
    "expiry_day" int DEFAULT NULL,
    "weight" decimal(24, 6) DEFAULT NULL,
    "purchase_price" decimal(24, 6) DEFAULT NULL,
    "sale_price" decimal(24, 6) DEFAULT NULL,
    "min_price" decimal(24, 6) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id")
) COMMENT 'ERP product';

CREATE TABLE IF NOT EXISTS "erp_kingdee_purchase_order_sync_record" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "source_form_id" varchar(64) NOT NULL,
    "source_fid" varchar(64) NOT NULL,
    "source_bill_no" varchar(128) NOT NULL,
    "purchase_order_id" bigint NOT NULL,
    "sync_status" tinyint NOT NULL,
    "failure_message" varchar(512) DEFAULT NULL,
    "raw_payload" clob DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_erp_kingdee_po_sync_tenant_source" UNIQUE ("tenant_id", "source_form_id", "source_fid", "deleted")
) COMMENT 'ERP Kingdee purchase order sync record';

CREATE TABLE IF NOT EXISTS "erp_kingdee_event_callback" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "event_key" varchar(191) NOT NULL,
    "event_id" varchar(128) DEFAULT NULL,
    "source_form_id" varchar(64) NOT NULL,
    "source_fid" varchar(64) DEFAULT NULL,
    "source_bill_no" varchar(128) DEFAULT NULL,
    "operation" varchar(64) NOT NULL,
    "event_time" timestamp NOT NULL,
    "signature" varchar(128) NOT NULL,
    "nonce" varchar(64) NOT NULL,
    "callback_timestamp" varchar(64) NOT NULL,
    "status" tinyint NOT NULL DEFAULT 0,
    "failure_message" varchar(512) DEFAULT NULL,
    "raw_payload" clob NOT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT '0',
    PRIMARY KEY ("id"),
    CONSTRAINT "uk_erp_kingdee_event_callback_event_key" UNIQUE ("event_key")
) COMMENT 'ERP Kingdee event callback';
